/* 0x02013c3c (0xb4 bytes) Camera_chainKeys (Ghidra: FUN_02013c3c)
 * file: name */
/* The keys of a camera in a chain (Game_loadCameras put them in world units); loop: the last goes
 * on to the first */
void Camera_chainKeys( Camera *self, int loop ) {
	int i;

	self->keyDone = 0;
	for ( i = 0; i < self->numKeys; i++ ) {
		CameraKey *k = &self->keys[i];
		if ( i < self->numKeys - 1 ) {
			k->next = &self->keys[i + 1];
		} else {
			k->next = loop ? self->keys : NULL;
		}
		if ( i >= 1 ) {
			k->prev = &self->keys[i - 1];
		} else {
			k->prev = loop ? &self->keys[self->numKeys - 1] : NULL;
		}
	}
}

/* 0x02013cf0 (0x8c bytes) Camera_snapToKey (Ghidra: FUN_02013cf0)
 * file: name */
/* The camera at the end of key (a skipped cinematic); the waiting thread runs on */
void Camera_snapToKey( Camera *self, int key ) {
	CameraKey *k;

	if ( self->curKey == key && self->keyDone ) {
		return;
	}
	self->curKey = key;
	k = &self->keys[key];
	if ( k->next ) {
		k = k->next;
	}
	self->x = k->x << 12;
	self->y = k->y << 12;
	self->z = k->z << 12;
	self->pitch = k->pitch;
	self->yaw = k->yaw;
	self->roll = k->roll;
	ScriptThread_run( self->thread );
	self->keyDone = 1;
}

