	self->z = Camera_spline( self, t, prev->z, k->z, next->z, next2->z );
	self->pitch = Camera_splineAngle( self, t, prev->pitch, k->pitch, next->pitch, next2->pitch );
	self->yaw = Camera_splineAngle( self, t, prev->yaw, k->yaw, next->yaw, next2->yaw );
